/**
 * SillyTavernchat Module - Account password helpers
 *
 * OAuth-created accounts get a random, never-disclosed password so that the official
 * handle-only login (users-public.js skips the check for empty passwords) cannot be used
 * to enter them. Such accounts are flagged with `passwordAutoGenerated` in STC metadata;
 * the user may later set a real password without knowing the generated one.
 */
import crypto from 'node:crypto';
import { getPasswordSalt } from '../../users.js';

/** OAuth providers whose accounts are managed by STC-MOD. */
export const OAUTH_PROVIDERS = Object.freeze(['github', 'discord', 'linuxdo', 'qrole']);

/**
 * Metadata whose createdAt differs from the official record's `created` by more than this
 * belongs to a deleted account whose handle was re-used (the official delete keeps STC metadata).
 */
export const STALE_METADATA_TOLERANCE_MS = 10 * 60 * 1000;

/**
 * Generate a random password nobody knows.
 * @returns {string}
 */
export function generateRandomPassword() {
    return crypto.randomBytes(32).toString('base64url');
}

/**
 * Give a user record a password nobody knows (mutates and returns it).
 * Stores random bytes in the same format as getPasswordHash (base64 of 64 bytes): with no
 * known preimage it can never match a login attempt, and it skips the ~50 ms scrypt cost.
 * @param {{password: string, salt: string}} user Official user record
 * @returns {{password: string, salt: string}}
 */
export function applyRandomPassword(user) {
    user.salt = getPasswordSalt();
    user.password = crypto.randomBytes(64).toString('base64');
    return user;
}

/**
 * Whether STC metadata belongs to the given official record (and not to a deleted account that
 * used the same handle). Metadata without timestamps is assumed to belong to the record.
 * @param {object|null|undefined} meta STC user metadata
 * @param {{created?: number}|null|undefined} record Official user record
 * @returns {boolean}
 */
export function isMetaForRecord(meta, record) {
    if (!meta || !record) return false;
    const metaCreated = Number(meta.createdAt);
    const recordCreated = Number(record.created);
    if (!metaCreated || !recordCreated) return true;
    return Math.abs(metaCreated - recordCreated) <= STALE_METADATA_TOLERANCE_MS;
}

/**
 * The metadata if it belongs to the record, otherwise null (stale metadata is ignored).
 * @param {object|null|undefined} meta STC user metadata
 * @param {{created?: number}|null|undefined} record Official user record
 * @returns {object|null}
 */
export function liveMetaForRecord(meta, record) {
    return isMetaForRecord(meta, record) ? meta : null;
}

/**
 * Whether the account's stored password was generated by STC-MOD (unknown to the user).
 * @param {object|null|undefined} meta STC user metadata
 * @returns {boolean}
 */
export function isPasswordAutoGenerated(meta) {
    return meta?.passwordAutoGenerated === true;
}

/**
 * Whether the user has a password they actually know (non-empty hash, not auto-generated).
 * @param {{password?: string}|null|undefined} user Official user record
 * @param {object|null|undefined} meta STC user metadata
 * @returns {boolean}
 */
export function userHasKnownPassword(user, meta) {
    return !!(user?.password && user.password.length > 0) && !isPasswordAutoGenerated(meta);
}
